self.addEventListener("install",function(n){self.skipWaiting()}),self.addEventListener("activate",function(n){n.waitUntil(caches.keys().then(function(t){return Promise.all(t.map(function(e){return caches.delete(e)}))}).then(function(){return self.registration.unregister()}).then(function(){return self.clients.matchAll({includeUncontrolled:!0})}).then(function(t){t.forEach(function(e){try{e.navigate(e.url)}catch(i){}})}).catch(function(){}))}),self.addEventListener("message",function(n){n.data==="SKIP_WAITING"&&self.skipWaiting()});
